@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + researchKeywords : string[]
}

class Institution {
  + institutionCode : int
  + address : string
}

class ScientificArticle {
  + DOI : string
  + title : string
  + authors : Person[]
  + position : int[]
}

abstract class ArticleType {}

class PeerReviewedPaper extends ArticleType {
  + citationCount : int
  + reviewers : Person[]
}

class TechnicalReport extends ArticleType {
  + publisher : Institution
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
  + publisher : Publisher
}

Person "1" -- "0..*" ScientificArticle : author
Person "1" -- "0..*" ScientificArticle : reviewer
ScientificArticle "1" -- "1" ArticleType
PeerReviewedPaper "1" -- "*" Reviewer
TechnicalReport "1" -- "1" Institution
Publisher "1" *-- "1..*" Journal

@enduml

